.labmarketsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1b1f3a;
    background: linear-gradient(165deg, #eef0fb 0%, #e6e9f7 100%);
    border-radius: 18px;
}

.labmarketsim-container * {
    box-sizing: border-box;
}

.labmarketsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #221c5e 0%, #3a2e8f 50%, #4f3fb0 100%);
    color: #f4f3ff;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(34, 28, 94, 0.32);
    position: relative;
    overflow: hidden;
}

.labmarketsim-header::after {
    content: "";
    position: absolute;
    top: -40%;
    right: -10%;
    width: 280px;
    height: 280px;
    background: radial-gradient(circle, rgba(45, 212, 218, 0.22) 0%, rgba(45, 212, 218, 0) 70%);
    pointer-events: none;
}

.labmarketsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.labmarketsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #b9f4f7;
    background: rgba(255, 255, 255, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
    position: relative;
    z-index: 1;
}

.labmarketsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #ddd9fb;
    position: relative;
    z-index: 1;
}

.labmarketsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #322a78;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.labmarketsim-period-counter #currentDay,
.labmarketsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #221c5e;
}

.labmarketsim-round-name {
    background: #ddd9fb;
    color: #322a78;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.labmarketsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b23a1e;
    background: #fbe4dc;
    padding: 4px 12px;
    border-radius: 999px;
}

.labmarketsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.labmarketsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #ddd9f2;
    box-shadow: 0 4px 14px rgba(34, 28, 94, 0.07);
    border-top: 4px solid #4f3fb0;
}

.labmarketsim-card-readiness { border-top-color: #1aa6a0; }
.labmarketsim-card-leverage { border-top-color: #d98c1a; }
.labmarketsim-card-value { border-top-color: #4f3fb0; }
.labmarketsim-card-budget { border-top-color: #2f6fb0; }

.labmarketsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a6796;
}

.labmarketsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #221c5e;
}

.labmarketsim-card-readiness .labmarketsim-value { color: #128c87; }
.labmarketsim-card-leverage .labmarketsim-value { color: #b9740f; }
.labmarketsim-card-value .labmarketsim-value { color: #4f3fb0; }
.labmarketsim-card-budget .labmarketsim-value { color: #2f6fb0; }

.labmarketsim-sublabel {
    font-size: 0.76rem;
    color: #7c79a0;
    line-height: 1.35;
}

.labmarketsim-readiness-hit .labmarketsim-value { color: #0e7a4f; }
.labmarketsim-leverage-hit .labmarketsim-value { color: #0e7a4f; }
.labmarketsim-budget-over { border-top-color: #c0392b; }
.labmarketsim-budget-over .labmarketsim-value { color: #c0392b; }

.labmarketsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #221c5e;
    color: #eceafb;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.labmarketsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.labmarketsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #2dd4da;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(34, 28, 94, 0.06);
}

.labmarketsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.labmarketsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #221c5e;
    margin-bottom: 6px;
}

.labmarketsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a3866;
}

.labmarketsim-briefing-text strong { color: #128c87; }
.labmarketsim-briefing-text em { color: #b23a1e; font-style: italic; }

.labmarketsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #ddd9f2;
    box-shadow: 0 4px 14px rgba(34, 28, 94, 0.07);
}

.labmarketsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #221c5e;
    border-bottom: 2px solid #e9e6f7;
    padding-bottom: 8px;
}

.labmarketsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2b2858;
    margin: 14px 0 6px;
}

.labmarketsim-container select,
.labmarketsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c7c2e6;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f8f7fd;
    color: #1b1f3a;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.labmarketsim-container select:focus,
.labmarketsim-container input[type="number"]:focus {
    outline: none;
    border-color: #4f3fb0;
    box-shadow: 0 0 0 3px rgba(79, 63, 176, 0.16);
}

.labmarketsim-container select option {
    background-color: #ffffff;
    color: #1b1f3a;
}

.labmarketsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #4f3fb0;
}

.labmarketsim-range-readout,
.labmarketsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #4338a0;
    margin-top: 4px;
}

.labmarketsim-range-readout span:last-child,
.labmarketsim-alloc-readout span:nth-child(2) {
    color: #128c87;
    font-weight: 800;
}

.labmarketsim-hint {
    font-size: 0.8rem;
    color: #7c79a0;
    margin-top: 4px;
    line-height: 1.4;
}

.labmarketsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.labmarketsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f4f3fc;
    border: 1px solid #e2def5;
    border-radius: 9px;
    padding: 8px 12px;
}

.labmarketsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #2b2858;
}

.labmarketsim-alloc-row input[type="number"] {
    width: 100px;
    flex: 0 0 100px;
}

.labmarketsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.labmarketsim-container .btn-primary {
    background: linear-gradient(135deg, #4f3fb0 0%, #1aa6a0 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(79, 63, 176, 0.30);
}

.labmarketsim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.labmarketsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c7c2e6;
    color: #6a6796;
}

.labmarketsim-coach {
    background: #221c5e;
    color: #eceafb;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(34, 28, 94, 0.24);
}

.labmarketsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #7fe6ea;
    margin-bottom: 8px;
}

.labmarketsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.labmarketsim-coach-body strong { color: #ffd98a; }
.labmarketsim-coach-body em { color: #ffb9a6; font-style: italic; }

.labmarketsim-history,
.labmarketsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #ddd9f2;
    box-shadow: 0 4px 14px rgba(34, 28, 94, 0.07);
}

.labmarketsim-history h3,
.labmarketsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #221c5e;
}

.labmarketsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2b2858;
}

.labmarketsim-container table#usfHistoryTable th {
    background: #efedfa;
    color: #221c5e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #ddd9f2;
}

.labmarketsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0eef9;
}

.labmarketsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf9fe;
}

.labmarketsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .labmarketsim-container {
        padding: 14px;
    }
    .labmarketsim-header h1 {
        font-size: 1.7rem;
    }
    .labmarketsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .labmarketsim-value {
        font-size: 2rem;
    }
    .labmarketsim-clock {
        margin-left: 0;
    }
    .labmarketsim-period-counter {
        font-size: 0.88rem;
    }
    .labmarketsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .labmarketsim-alloc-row {
        flex-wrap: wrap;
    }
    .labmarketsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .labmarketsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion-message card (appended; dark-on-light, self-contained) */
.labmarketsim-cm { background:#f4f4fb; color:#1a1930; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(0,0,0,0.18); }
.labmarketsim-cm-head { text-align:center; border-bottom:1px solid #dcdaef; padding-bottom:14px; margin-bottom:16px; }
.labmarketsim-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#575379; font-weight:700; }
.labmarketsim-cm-scorewrap { margin:8px 0 2px; }
.labmarketsim-cm-score { font-size:52px; font-weight:800; color:#514bb0; line-height:1; }
.labmarketsim-cm-score-max { font-size:20px; color:#8b88ac; font-weight:600; }
.labmarketsim-cm-grade { font-size:19px; font-weight:700; color:#1a1930; margin-top:4px; }
.labmarketsim-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.labmarketsim-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.labmarketsim-cm-met { background:#d3e7de; color:#1c6a4e; }
.labmarketsim-cm-fail { background:#f1dbdb; color:#a13630; }
.labmarketsim-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.labmarketsim-cm-metric { background:#e7e6f4; border-radius:10px; padding:12px 16px; min-width:104px; text-align:center; }
.labmarketsim-cm-metric-val { font-size:22px; font-weight:800; color:#1a1930; }
.labmarketsim-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#575379; margin-top:3px; }
.labmarketsim-cm-insights { background:#e7e6f4; border-radius:10px; padding:14px 18px; }
.labmarketsim-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#575379; font-weight:700; margin-bottom:8px; }
.labmarketsim-cm-insights ul { margin:0; padding-left:18px; }
.labmarketsim-cm-insights li { font-size:14px; line-height:1.5; color:#2f2d42; margin-bottom:7px; }

