(function() {
    'use strict';

    class LabMarketAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `From Lab to Market`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (EUR, in €k where money).
            this.SEED_FUND = 600;          // €600k proof-of-concept seed fund
            this.PATENT_COST = 180;        // €180k national-phase filing
            this.VALIDATION_COST = 450;    // €450k field validation, TRL 4 -> 7
            this.START_READINESS = 40;     // 40/100 == TRL 4
            this.BUYER_READINESS = 70;     // 70/100 == TRL 7
            this.LEVERAGE_TARGET = 150;    // 1.5x external per internal euro (stored x100)

            // External co-funding pulled in by each partner (€k).
            this.PARTNER_COFUND = { construction: 400, multinational: 250, vc: 1200, none: 0 };

            // Concept truths.
            this.TRUE_CONSTRAINT = `readiness`;
            this.TRUE_PATHWAY = `jda`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    readiness: this.START_READINESS,
                    leverage: 0,
                    value: 20,
                    budgetUsed: 0,
                    internalSpend: 0,
                    externalRaised: 0,
                    patentSecured: false,
                    pathway: ``,
                    partner: ``,
                    readinessHistory: [this.START_READINESS],
                    leverageHistory: [0],
                    valueHistory: [20],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a MIDDLING / neutral mix — never the textbook-correct play.
                state.decisions = {
                    constraint: `cash`,
                    evidence: `lab`,
                    honesty: 50,
                    pathway: `license`,
                    inventor: `recruit`,
                    milestone: `signing`,
                    fit: 50,
                    patent: 180,
                    validation: 300,
                    filing: `all`,
                    partner: `multinational`,
                    sequence: `validatefirst`,
                    kpi: `value`,
                    contingency: `inventor`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const con = document.getElementById(`constraintInput`);
                const ev = document.getElementById(`evidenceInput`);
                const hon = document.getElementById(`honestyInput`);
                if (con) decisions.constraint = con.value;
                if (ev) decisions.evidence = ev.value;
                if (hon) decisions.honesty = parseInt(hon.value, 10);
                if (!Number.isFinite(decisions.honesty) || decisions.honesty < 0 || decisions.honesty > 100) {
                    warn(`warn_honesty_range`); return false;
                }
            } else if (round === 2) {
                const pa = document.getElementById(`pathwayInput`);
                const inv = document.getElementById(`inventorInput`);
                const ms = document.getElementById(`milestoneInput`);
                const fit = document.getElementById(`fitInput`);
                if (pa) decisions.pathway = pa.value;
                if (inv) decisions.inventor = inv.value;
                if (ms) decisions.milestone = ms.value;
                if (fit) decisions.fit = parseInt(fit.value, 10);
                if (!Number.isFinite(decisions.fit) || decisions.fit < 0 || decisions.fit > 100) {
                    warn(`warn_fit_range`); return false;
                }
            } else if (round === 3) {
                const pat = document.getElementById(`patentInput`);
                const val = document.getElementById(`validationInput`);
                const fil = document.getElementById(`filingInput`);
                const prt = document.getElementById(`partnerInput`);
                if (pat) decisions.patent = parseFloat(pat.value);
                if (val) decisions.validation = parseFloat(val.value);
                if (fil) decisions.filing = fil.value;
                if (prt) decisions.partner = prt.value;
                if (!Number.isFinite(decisions.patent) || decisions.patent < 0) {
                    warn(`warn_patent_negative`); return false;
                }
                if (!Number.isFinite(decisions.validation) || decisions.validation < 0) {
                    warn(`warn_validation_negative`); return false;
                }
                const spent = Math.round(decisions.patent + decisions.validation);
                if (spent > this.SEED_FUND) {
                    warn(`warn_overbudget`); return false;
                }
            } else if (round === 4) {
                const sq = document.getElementById(`sequenceInput`);
                const kp = document.getElementById(`kpiInput`);
                const ct = document.getElementById(`contingencyInput`);
                const cv = document.getElementById(`convictionInput`);
                if (sq) decisions.sequence = sq.value;
                if (kp) decisions.kpi = kp.value;
                if (ct) decisions.contingency = ct.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // readinessDelta = progress toward TRL 7; valueDelta = strategic+financial value retained.
            let readinessDelta = 0, valueDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose readiness honestly (Common Error 5: readiness denial).
                if (d.constraint === this.TRUE_CONSTRAINT) {
                    valueDelta += 10; readinessDelta += 4; coachKey = `coach_r1_constraint_right`;
                } else if (d.constraint === `none`) {
                    valueDelta -= 14; readinessDelta -= 6; coachKey = `coach_r1_constraint_none`;
                } else if (d.constraint === `time`) {
                    valueDelta -= 4; coachKey = `coach_r1_constraint_time`;
                } else {
                    valueDelta += 2; coachKey = `coach_r1_constraint_cash`;
                }

                // Evidence: a field demo is what TRL 7 demands; re-running the bench or "publish it" is denial.
                if (d.evidence === `field`) {
                    valueDelta += 7; readinessDelta += 4;
                    if (d.constraint === this.TRUE_CONSTRAINT) coachKey = `coach_r1_diag_sharp`;
                } else if (d.evidence === `paper`) {
                    valueDelta -= 10; readinessDelta -= 4; coachKey = `coach_r1_paper`;
                } else {
                    valueDelta -= 4; coachKey = `coach_r1_lab`;
                }

                // Honesty about the gap.
                if (d.honesty >= 60) { valueDelta += 6; }
                else if (d.honesty <= 25) { valueDelta -= 8; coachKey = `coach_r1_lowhonesty`; }

                summaryKey = (d.constraint === this.TRUE_CONSTRAINT && d.evidence === `field`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                ds.pathway = d.pathway;

                // Pathway fit (Common Errors 1 & 3). JDA fits a TRL-4 asset + reluctant inventor +
                // two clocks; the spin-off is upside-chasing; the bare license surrenders control.
                if (d.pathway === this.TRUE_PATHWAY) {
                    valueDelta += 12; readinessDelta += 6; coachKey = `coach_r2_jda`;
                } else if (d.pathway === `spinoff`) {
                    valueDelta -= 8; coachKey = `coach_r2_spinoff`;
                } else if (d.pathway === `license`) {
                    valueDelta -= 6; coachKey = `coach_r2_license`;
                }

                // Key-person risk. Forcing the reluctant inventor into CEO is the spin-off trap;
                // it is rewarded slightly LESS even than keeping her as advisor.
                if (d.inventor === `advisor`) {
                    valueDelta += 7;
                } else if (d.inventor === `recruit`) {
                    valueDelta += 4;
                } else if (d.inventor === `forceceo`) {
                    valueDelta -= 10;
                    coachKey = (d.pathway === `spinoff`) ? `coach_r2_founderless` : `coach_r2_forceceo`;
                }

                // Milestone-based value transfer beats handing rights over at signing.
                if (d.milestone === `trl7`) { valueDelta += 6; readinessDelta += 2; }
                else if (d.milestone === `signing`) { valueDelta -= 6; coachKey = `coach_r2_signing`; }
                else { valueDelta -= 8; coachKey = `coach_r2_never`; }

                // Discipline of matching pathway to context, not chasing upside.
                if (d.fit >= 60) { valueDelta += 5; }
                else if (d.fit <= 25) { valueDelta -= 6; }

                summaryKey = (d.pathway === this.TRUE_PATHWAY && d.inventor !== `forceceo` && d.milestone === `trl7`) ? `sum_r2_good` :
                    (d.pathway === `spinoff` ? `sum_r2_upside` : `sum_r2_weak`);
            } else if (round === 3) {
                ds.partner = d.partner;
                const internalSpend = Math.round(d.patent + d.validation); // seed fund actually deployed
                ds.budgetUsed = Math.min(this.SEED_FUND, internalSpend);
                ds.internalSpend = internalSpend;

                // Patent protection (Common Error 4: IP over-filing).
                if (d.filing === `focused`) {
                    if (d.patent >= 150) { ds.patentSecured = true; valueDelta += 12; coachKey = `coach_r3_focused`; }
                    else { valueDelta -= 4; coachKey = `coach_r3_underfiled`; }
                } else if (d.filing === `all`) {
                    if (d.patent >= 320) { ds.patentSecured = true; valueDelta -= 4; coachKey = `coach_r3_overfile`; }
                    else { valueDelta -= 10; coachKey = `coach_r3_overfile_short`; }
                } else { // abandon
                    valueDelta -= 16; coachKey = `coach_r3_abandon`;
                }

                // External co-funding pulled in by the partner.
                let cofund = this.PARTNER_COFUND[d.partner] || 0;
                let usableCofund = cofund;
                if (d.partner === `vc`) {
                    // The VC's €1.2M is conditional on the inventor LEAVING academia to run it —
                    // i.e. it is only real on a spin-off where the inventor takes the CEO seat.
                    // An external CEO or keeping her as advisor does not unlock the conditional
                    // capital, so its leverage is hollow (Common Error 1: upside-chasing).
                    const founderTakesCeo = ds.pathway === `spinoff` && state.decisions.inventor === `forceceo`;
                    if (!founderTakesCeo) {
                        usableCofund = cofund * 0.1; valueDelta -= 8; coachKey = `coach_r3_vc_conditional`;
                    } else {
                        // Capital unlocked, but it cost the reluctant founder the CEO chair and 35%
                        // equity — high key-person risk and heavy dilution erode value capture.
                        valueDelta -= 10; coachKey = `coach_r3_vc_conditional`;
                    }
                } else if (d.partner === `multinational`) {
                    // Clean cash, but a conflicted incumbent who may shelve a disruptive material
                    // (Common Error 3: control surrender).
                    valueDelta -= 10; coachKey = `coach_r3_multinational`;
                } else if (d.partner === `construction`) {
                    valueDelta += 6;
                } else { // none
                    coachKey = `coach_r3_nopartner`;
                }

                ds.externalRaised = Math.round(usableCofund);

                // Validation crosses the valley of death = internal validation spend + partner
                // co-funding toward the ~€450k field-validation need. Co-funding counted toward
                // validation is capped at the actual gap (excess capital does not over-mature it).
                const partnerToValidation = (d.partner === `construction` || d.partner === `vc`)
                    ? Math.min(usableCofund, this.VALIDATION_COST) : 0;
                const validationFunded = d.validation + partnerToValidation;
                let readinessGain = Math.min(30, (validationFunded / this.VALIDATION_COST) * 30);
                readinessDelta += Math.round(readinessGain);

                // Funding leverage = external CO-FUNDING euros raised per internal euro deployed
                // (stored x100). This is the office's blended-finance discipline: dilutive VC equity
                // is NOT co-funding leverage on the seed fund, so it does not count here — the JDA's
                // non-dilutive co-funding is the intended lever. Capped at 250 (2.5×).
                const cofundForLeverage = (d.partner === `vc`) ? 0 : usableCofund;
                if (internalSpend > 0) {
                    ds.leverage = Math.min(250, Math.round((cofundForLeverage / internalSpend) * 100));
                } else {
                    ds.leverage = 0;
                }

                // Leverage discipline (Common Error 2: leverage blindness). Spending the whole
                // seed fund internally with no partner mobilizes zero external euros.
                if (ds.leverage >= this.LEVERAGE_TARGET) { valueDelta += 12; }
                else if (ds.leverage === 0 && internalSpend >= 450) { valueDelta -= 12; coachKey = `coach_r3_noleverage`; }
                else if (ds.leverage < 80 && d.partner !== `none`) { valueDelta -= 2; }

                summaryKey = (d.partner === `construction` && d.filing === `focused` && ds.leverage >= this.LEVERAGE_TARGET) ? `sum_r3_good` :
                    (ds.leverage === 0 ? `sum_r3_noleverage` : `sum_r3_weak`);
            } else if (round === 4) {
                // Sequencing against irreversible deadlines (Common Error: loose sequencing).
                if (d.sequence === `deadline`) {
                    valueDelta += 12; readinessDelta += 4; coachKey = `coach_r4_deadline`;
                } else if (d.sequence === `validatefirst`) {
                    valueDelta -= 8; coachKey = `coach_r4_validatefirst`;
                } else {
                    valueDelta -= 14; readinessDelta -= 2; coachKey = `coach_r4_loose`;
                }

                // Exit KPIs: the full set including leverage beats a headline-value pitch.
                if (d.kpi === `full`) { valueDelta += 10; }
                else if (d.kpi === `value`) { valueDelta -= 6; coachKey = `coach_r4_kpivalue`; }
                else { valueDelta -= 8; coachKey = `coach_r4_kpinone`; }

                // Contingency for inventor exit AND validation slip.
                if (d.contingency === `both`) {
                    valueDelta += 12; readinessDelta += 2; coachKey = (d.sequence === `deadline`) ? `coach_r4_robust` : coachKey;
                } else if (d.contingency === `inventor`) {
                    valueDelta += 2;
                } else {
                    valueDelta -= 10; coachKey = `coach_r4_nocontingency`;
                }

                // Conviction nudges value.
                valueDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.sequence === `deadline` && d.kpi === `full` && d.contingency === `both`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Compress the value deltas so the optimal play does NOT peg the 0–100
            // meter at 100 before the final round — keeping every late lever and each
            // single-decision error visible instead of masked by the clamp.
            valueDelta = valueDelta * 0.6;

            // Apply deltas with clamping.
            ds.readiness = Math.max(0, Math.min(100, ds.readiness + readinessDelta));
            ds.value = Math.max(0, Math.min(100, ds.value + valueDelta));

            ds.readinessHistory.push(Math.round(ds.readiness));
            ds.leverageHistory.push(Math.round(ds.leverage));
            ds.valueHistory.push(Math.round(ds.value));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            // v1.1.0 fix: persist instructor-card composite to domainState every period.
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                readiness: Math.round(ds.readiness),
                trl: this._trl(ds.readiness),
                readinessDelta: Math.round(readinessDelta),
                leverage: Math.round(ds.leverage),
                value: Math.round(ds.value),
                valueDelta: Math.round(valueDelta),
                budgetUsed: ds.budgetUsed,
                externalRaised: ds.externalRaised,
                patentSecured: ds.patentSecured,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _trl(readiness) {
            // Map the 0-100 readiness meter onto the TRL 1-9 scale (40 == TRL 4, 70 == TRL 7).
            let trl = 4 + (readiness - this.START_READINESS) / 10;
            trl = Math.max(1, Math.min(9, trl));
            return Math.round(trl * 10) / 10;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            uiManager.bind(`readinessDisplay`, `domainState.readiness`, (v) => {
                const card = document.querySelector(`.labmarketsim-card-readiness`);
                if (card) card.classList.toggle(`labmarketsim-readiness-hit`, Number(v) >= this.BUYER_READINESS);
                return `TRL ` + this._trl(Number(v)).toFixed(1);
            });
            uiManager.bind(`leverageDisplay`, `domainState.leverage`, (v) => {
                const card = document.querySelector(`.labmarketsim-card-leverage`);
                if (card) card.classList.toggle(`labmarketsim-leverage-hit`, Number(v) >= this.LEVERAGE_TARGET);
                return (Number(v) / 100).toFixed(1) + `×`;
            });
            uiManager.bind(`valueDisplay`, `domainState.value`, (v) => Math.round(Number(v)));
            uiManager.bind(`budgetCardDisplay`, `domainState.budgetUsed`, (v) => this._money(Number(v)));
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const card = document.querySelector(`.labmarketsim-card-budget`);
                if (card) card.classList.toggle(`labmarketsim-budget-over`, Number(v) > this.SEED_FUND + 0.001);
                return this._money(Number(v)) + ` / ` + this._money(this.SEED_FUND);
            });

            const self = this;

            // Honesty slider readout.
            const hon = document.getElementById(`honestyInput`);
            const honReadout = document.getElementById(`honestyReadout`);
            if (hon && honReadout) {
                honReadout.textContent = hon.value;
                hon.addEventListener(`input`, function() { honReadout.textContent = hon.value; });
            }

            // Fit slider readout.
            const fit = document.getElementById(`fitInput`);
            const fitReadout = document.getElementById(`fitReadout`);
            if (fit && fitReadout) {
                fitReadout.textContent = fit.value;
                fit.addEventListener(`input`, function() { fitReadout.textContent = fit.value; });
            }

            // Seed-fund allocation live total + reserve.
            const allocIds = [`patentInput`, `validationInput`];
            const seedReadout = document.getElementById(`seedReadout`);
            const reserveReadout = document.getElementById(`reserveReadout`);
            const recompute = function() {
                let spent = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) spent += (parseFloat(el.value) || 0);
                });
                spent = Math.round(spent);
                const reserve = self.SEED_FUND - spent;
                if (seedReadout) seedReadout.textContent = spent;
                if (reserveReadout) reserveReadout.textContent = reserve;
                const bar = document.querySelector(`.labmarketsim-alloc-readout`);
                if (bar) bar.style.color = (spent > self.SEED_FUND) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        _money(v) {
            // Locale-aware EUR: English "€480k" (symbol before); Spanish "480 k€" (symbol after).
            const n = Math.round(Number(v) || 0);
            const lang = (window.mySimulation && window.mySimulation.language) || `en`;
            return (lang === `es`) ? (n + ` k€`) : (`€` + n + `k`);
        }

