        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.readinessHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : window.mySimulation.t(`chart_round_prefix`) + i));
            return {
                labmarketChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.readinessHistory },
                        { data: ds.leverageHistory },
                        { data: ds.valueHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.0.0 composite formula, verbatim — single source of truth.
            const readiness = Math.round(ds.readiness);
            const leverage = Math.round(ds.leverage);
            const value = Math.round(ds.value);
            return Math.round(Math.min(100, readiness) * 0.34 + Math.min(100, leverage / 2) * 0.33 + value * 0.33);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const readiness = Math.round(ds.readiness);
            const trl = this._trl(ds.readiness);
            const leverage = Math.round(ds.leverage);
            const value = Math.round(ds.value);

            const hitReadiness = readiness >= this.BUYER_READINESS;
            const hitLeverage = leverage >= this.LEVERAGE_TARGET;
            const composite = this._composite(ds);

            let performance = window.mySimulation.t(`perf_stalled`);
            if (hitReadiness && hitLeverage && ds.patentSecured && composite >= 70) performance = window.mySimulation.t(`perf_lab_to_market`);
            else if (hitReadiness && hitLeverage) performance = window.mySimulation.t(`perf_credible`);
            else if (hitReadiness && !hitLeverage) performance = window.mySimulation.t(`perf_unleveraged`);
            else if (hitLeverage && !hitReadiness) performance = window.mySimulation.t(`perf_underfunded_gap`);
            else if (readiness > this.START_READINESS + 12) performance = window.mySimulation.t(`perf_improving`);

            const insights = [];
            if (hitReadiness && hitLeverage && ds.patentSecured) insights.push(window.mySimulation.t(`insight_crossed`));
            else if (!hitReadiness) insights.push(window.mySimulation.t(`insight_valley`));
            if (leverage === 0) insights.push(window.mySimulation.t(`insight_noleverage`));
            else if (!hitLeverage) insights.push(window.mySimulation.t(`insight_lowleverage`));
            if (!ds.patentSecured) insights.push(window.mySimulation.t(`insight_nopatent`));
            if (ds.partner === `multinational`) insights.push(window.mySimulation.t(`insight_control`));
            if (ds.pathway === `spinoff`) insights.push(window.mySimulation.t(`insight_spinoff`));
            if (hitReadiness && hitLeverage && value >= 60) insights.push(window.mySimulation.t(`insight_balanced`));

            return {
                readiness: readiness,
                trl: trl,
                leverage: leverage,
                value: value,
                hitReadiness: hitReadiness,
                hitLeverage: hitLeverage,
                patentSecured: ds.patentSecured,
                composite: composite,
                performance: performance,
                met: hitReadiness && hitLeverage && ds.patentSecured && composite >= 70,
                patentSecured: ds.patentSecured,
                partner: ds.partner,
                pathway: ds.pathway,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k, v) => window.mySimulation.t(k, v);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || ``;
            const badges = [];
            badges.push(`<span class="labmarketsim-cm-badge ` + (s.met ? `labmarketsim-cm-met` : `labmarketsim-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.hitReadiness === false) badges.push(`<span class="labmarketsim-cm-badge labmarketsim-cm-fail">` + t(`cm_fail_readiness`) + `</span>`);
            if (s.hitLeverage === false) badges.push(`<span class="labmarketsim-cm-badge labmarketsim-cm-fail">` + t(`cm_fail_leverage`) + `</span>`);
            if (s.patentSecured === false) badges.push(`<span class="labmarketsim-cm-badge labmarketsim-cm-fail">` + t(`cm_fail_patent`) + `</span>`);
            const kpi = (label, val) => `<div class="labmarketsim-cm-metric"><div class="labmarketsim-cm-metric-val">` + val + `</div><div class="labmarketsim-cm-metric-lbl">` + label + `</div></div>`;
            const trlv = (s.trl != null) ? `TRL ` + Number(s.trl).toFixed(1) : ``;
            const levv = ((s.leverage != null ? s.leverage : 0) / 100).toFixed(1) + `×`;
            const kpis = kpi(t(`cm_readiness`), (s.readiness != null ? Math.round(s.readiness) : 0))
                + kpi(t(`cm_trl`), trlv)
                + kpi(t(`cm_leverage`), levv)
                + kpi(t(`cm_value`), (s.value != null ? Math.round(s.value) : 0));
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="labmarketsim-cm">`
                + `<div class="labmarketsim-cm-head"><div class="labmarketsim-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="labmarketsim-cm-scorewrap"><span class="labmarketsim-cm-score">` + score + `</span><span class="labmarketsim-cm-score-max">/100</span></div>`
                + `<div class="labmarketsim-cm-grade">` + grade + `</div>`
                + `<div class="labmarketsim-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="labmarketsim-cm-metrics">` + kpis + `</div>`
                + `<div class="labmarketsim-cm-insights"><div class="labmarketsim-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (state.currentPeriod >= 3 && ds.leverage === 0) return window.mySimulation.t(`hint_leverage`);
            if (state.currentPeriod >= 3 && !ds.patentSecured) return window.mySimulation.t(`hint_patent`);
            if (state.currentPeriod >= 3 && ds.readiness < this.BUYER_READINESS) return window.mySimulation.t(`hint_readiness`);
            if (ds.value < 30) return window.mySimulation.t(`hint_value`);
            if (ds.readiness >= this.BUYER_READINESS && ds.leverage >= this.LEVERAGE_TARGET) return window.mySimulation.t(`hint_strong`);
            return null;
        }

