                { key: `results.trl`, label: `TRL`, i18nKey: `col_trl`, formatter: (v) => `TRL ` + Number(v).toFixed(1) },
                { key: `results.leverage`, label: `Leverage`, i18nKey: `col_leverage`, formatter: (v) => (Number(v) / 100).toFixed(1) + `×` },
                { key: `results.value`, label: `Value`, i18nKey: `col_value`, formatter: (v) => Math.round(v) }
            ];
